        count[num] = count.get(num, 0) + 1
        if count[num] > len(nums) // 2:
            return num

def solve(nums): 
    '''Returns the value that appears more than len(nums)/2 times in the list nums.'''
    cadidat, count = None, 0
    for n in nums: 
        if not count:
            cadidat, count = n, 1
        elif n == cadidat:
            count += 1
        else:
            count -= 1
    return cadidat

def solve(nums):
    count = 0
    candidate = None
    for num in nums:
        if count == 0:
            candidate = num
        if num == candidate:
            count += 1
        else:
            count -= 1
    return candidate

